import fs from 'node:fs'; import cp from 'node:child_process'; import assert from 'node:assert/strict'; import {parse} from 'yaml'; import {R30_RULE_SHAPES} from './src/registry.ts'; import {validateRegistry,canonicalJson,bindingDigestFor,registryBindingManifestDigest,sha256,resolveAuthority} from './src/validate.ts';
const d=parse(fs.readFileSync('authority-enforcement-registry.yaml','utf8')); assert.equal(validateRegistry(d).valid,true);
const p=parse(cp.execFileSync('git',['show','66a514d35a384f901486e7b814580eb6fb7de6ea:plugins/foreman-line/authority-registry/authority-enforcement-registry.yaml'],{encoding:'utf8',maxBuffer:32000000}));assert.equal(canonicalJson(p.reconciliations),canonicalJson(d.reconciliations.slice(0,19)));assert.equal(canonicalJson(p.operationAuthority),canonicalJson(d.operationAuthority));assert.equal(canonicalJson(p.rules.filter(r=>r.decision==='ALLOW')),canonicalJson(d.rules.filter(r=>r.decision==='ALLOW')));
let n=0;for(const e of R30_RULE_SHAPES){const c=structuredClone(d),r=c.rules.find(r=>r.ruleId===e.ruleId);r.assurance=({'independent-review-human-judgment':'independently-verified','pre-action-refusal':'structural','post-action-detection':'detected','narrative-provenance':'narrative'})[r.classification];r.bindingDigest=bindingDigestFor(r);for(const v of c.reconciliations.at(-1).observedEvidence){if(v.kind!=='command-result')continue;const x=JSON.parse(v.reference);if(x.commandId.startsWith('superseding-binding-manifest')){x.resultDigest=registryBindingManifestDigest(c);v.reference=canonicalJson(x);v.digest=sha256(v.reference);}}const result=validateRegistry(c);assert.equal(result.valid,false);assert.ok(result.violations.some(v=>v.code==='AUTHORITY_ESCALATION'&&v.message.includes('reserved R30 rule')));n++;}
let np=0;for(const r of R30_RULE_SHAPES.filter(r=>r.classification==='narrative-provenance')){const result=resolveAuthority(d,{authoritySubject:r.authoritySubject,goal:'foreman-kernel',role:r.applicability.roles[0],stage:r.applicability.stages[0],operation:r.applicability.operations[0],host:'provider-neutral'});assert.equal(result.reasonCode,'NO_APPLICABLE_AUTHORITY');assert.deepEqual(result.controllingRuleIds,[]);np++;}console.log(JSON.stringify({valid:true,history:19,protectedAuthorityUnchanged:true,allowSetUnchanged:true,repairedAssuranceRefusals:n,noncontrollingProvenance:np}));
